import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:intl/intl.dart';import '../../../core/providers/app_providers.dart';import '../../../core/domain/care_entities.dart';import 'reminder_editor_screen.dart';import 'reminder_history_screen.dart';
class CareScheduleScreen extends ConsumerWidget{const CareScheduleScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final c=ref.watch(appControllerProvider);final list=c.items('reminders').map(Reminder.fromMap).toList()..sort((a,b)=>a.dueAt.compareTo(b.dueAt));return Scaffold(appBar:AppBar(title:const Text('Care schedule'),actions:[IconButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const ReminderHistoryScreen())),icon:const Icon(Icons.history)),IconButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const ReminderEditorScreen())),icon:const Icon(Icons.add))]),body:list.isEmpty?const Center(child:Text('No reminders yet. Add a routine when you are ready.')):ListView(padding:const EdgeInsets.all(16),children:[for(final r in list)Card(child:ListTile(leading:Icon(r.completed?Icons.check_circle:Icons.alarm,color:r.completed?Colors.green:const Color(0xFF39845A)),title:Text(r.title,style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text('${r.category} · ${DateFormat.yMMMd().add_jm().format(r.dueAt)} · ${r.repeat}'),trailing:Checkbox(value:r.completed,onChanged:(v)=>v==true?c.completeReminder(r):c.save('reminders',{...r.toMap(),'completed':0})),onLongPress:()=>showModalBottomSheet(context:context,builder:(ctx)=>SafeArea(child:Wrap(children:[ListTile(title:const Text('Snooze 10 minutes'),onTap:(){c.snoozeReminder(r,const Duration(minutes:10));Navigator.pop(ctx);}),ListTile(title:const Text('Pause / resume'),onTap:(){c.save('reminders',{...r.toMap(),'enabled':r.enabled?0:1});Navigator.pop(ctx);}),ListTile(title:const Text('Delete reminder'),onTap:(){c.delete('reminders',r.id);Navigator.pop(ctx);})]))))) ]));}}
